# criteria.schema.json

Generated, complete JSON Schema reference. Required/default/conditional rules are not inferred.

```json
{
  "$id": "https://coding-hermes.local/chd32/schemas/criteria.schema.json",
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "additionalProperties": false,
  "allOf": [
    {
      "if": {
        "properties": {
          "provenance": {
            "const": "standing_rule"
          }
        }
      },
      "then": {
        "properties": {
          "effective_rule_ref": {
            "minLength": 1,
            "type": "string"
          }
        },
        "required": [
          "effective_rule_ref"
        ]
      }
    }
  ],
  "description": "Versioned criterion with explicit provenance; every acceptance result must cite evidence references.",
  "properties": {
    "applies_to": {
      "minLength": 1,
      "type": "string"
    },
    "commit_seq": {
      "minimum": 1,
      "type": "integer"
    },
    "created_by": {
      "minLength": 1,
      "type": "string"
    },
    "criterion_id": {
      "minLength": 1,
      "type": "string"
    },
    "effective_rule_ref": {
      "type": [
        "string",
        "null"
      ]
    },
    "locked": {
      "type": "boolean"
    },
    "provenance": {
      "enum": [
        "vp_supplied",
        "director_derived",
        "standing_rule"
      ]
    },
    "record_id": {
      "minLength": 1,
      "type": "string"
    },
    "rev": {
      "minimum": 1,
      "type": "integer"
    },
    "schema_version": {
      "const": 3
    },
    "source_ref": {
      "type": [
        "string",
        "null"
      ]
    },
    "text": {
      "minLength": 1,
      "type": "string"
    },
    "version": {
      "minLength": 1,
      "type": "string"
    },
    "written_by": {
      "minLength": 1,
      "type": "string"
    }
  },
  "required": [
    "schema_version",
    "record_id",
    "rev",
    "commit_seq",
    "written_by",
    "criterion_id",
    "provenance",
    "version",
    "text",
    "applies_to"
  ],
  "title": "CHD AcceptanceCriterion v3",
  "type": "object"
}
```
